"""policy_engine.py  --  checks your Cedar rules on THIS computer with the real Cedar engine (the `cedarpy` package).   >>> YOU DO NOT EDIT THIS FILE <<<

Why: the AWS console tells you a rule is wrong only after you paste it. Here you test the same rule text first, with the same
logic AgentCore Policy uses (Cedar): everything is DENIED unless a `permit` rule matches, and a matching `forbid` rule always wins.

What the practice engine knows about a tool call (and nothing more):
    who is calling   (principal)    what they want (action = <target>___<tool>)    which door (resource = your Gateway)
    the tool's inputs (context.input.<name>)
It does NOT know the user database. It cannot look up "is this person a VIP?". Remember that for tab 4.
"""
import json
import re

import cedarpy

PREFIX = "askit-lambda___"
PLACEHOLDER = "{{GATEWAY_ARN}}"
PRACTICE_ARN = "arn:aws:bedrock-agentcore:us-east-1:000000000000:gateway/askit-gw-practice"
PRINCIPAL = ("AgentCore::IamEntity", "arn:aws:iam::000000000000:user/user1xx")   # our Gateway uses IAM sign-in, so callers are IAM identities
KNOWN_TOOLS = ("get_ticket", "get_user", "reset_password", "search_kb")


def render(text, arn):
    """Put your Gateway ARN into a rule (the starter files carry {{GATEWAY_ARN}})."""
    return text.replace(PLACEHOLDER, arn or PRACTICE_ARN)


def _entities(arn, tool):
    return [{"uid": {"type": PRINCIPAL[0], "id": PRINCIPAL[1]}, "attrs": {}, "parents": []},
            {"uid": {"type": "AgentCore::Gateway", "id": arn}, "attrs": {}, "parents": []},
            {"uid": {"type": "AgentCore::Action", "id": PREFIX + tool}, "attrs": {}, "parents": []}]


def lint(text, arn):
    """Plain-English checks for mistakes people make with AgentCore rules. Returns [(level, message)]; level is 'error' or 'warn'."""
    out = []
    t = text.strip()
    if not t:
        return out
    if PLACEHOLDER in t:
        out.append(("error", "The rule still contains {{GATEWAY_ARN}}. Paste your Gateway ARN in tab 1 and the app fills it in."))
    if re.search(r"action\s*==", t) and not re.search(r"resource\s*==", t):
        out.append(("error", "AgentCore needs a rule that names an action to also name ONE Gateway: resource == AgentCore::Gateway::\"<arn>\"."))
    if "OAuthUser" in t:
        out.append(("warn", "This rule only matches callers who log in with OAuth/JWT. Your Gateway uses IAM, so it would never match. Use plain `principal`."))
    for m in re.finditer(r'AgentCore::Action::"([^"]*)"', t):
        if not m.group(1).startswith(PREFIX):
            out.append(("warn", f'Action "{m.group(1)}" does not start with {PREFIX} . The name must be <target name>___<tool name>.'))
    if not t.rstrip().endswith(";"):
        out.append(("error", "A Cedar rule must end with a semicolon ;"))
    return out


def count_rules(text):
    try:
        return len(json.loads(cedarpy.policies_to_json_str(text)).get("staticPolicies", {}))
    except Exception:
        return 0


class Engine:
    """A practice policy engine. mode: 'ENFORCE' (block) or 'LOG_ONLY' (record what it WOULD do, block nothing).
    policies: list of (name, cedar text). Rules are checked together; names are only for the report."""

    def __init__(self, arn, mode, policies):
        self.arn = arn or PRACTICE_ARN
        self.mode = mode
        self.policies = [(n, render(t, self.arn)) for n, t in policies if t.strip()]
        self.log = []

    def _owner(self, rule_id):
        """cedar names rules policy0, policy1 ... in text order; map back to the box (name) it came from."""
        try:
            idx = int(rule_id.replace("policy", ""))
        except ValueError:
            return rule_id
        seen = 0
        for name, text in self.policies:
            n = max(1, count_rules(text))
            if idx < seen + n:
                return name
            seen += n
        return rule_id

    def parse_errors(self):
        errs = []
        for name, text in self.policies:
            r = cedarpy.is_authorized({"principal": f'{PRINCIPAL[0]}::"{PRINCIPAL[1]}"', "action": f'AgentCore::Action::"{PREFIX}get_ticket"',
                                       "resource": f'AgentCore::Gateway::"{self.arn}"', "context": {"input": {}}}, text, _entities(self.arn, "get_ticket"))
            for e in r.diagnostics.errors:
                if "parse" in e:
                    errs.append((name, e.replace("policy parse errors:\n", "").strip()))
        return errs

    def decide(self, tool, args):
        """-> dict(decision 'ALLOW'/'DENY', blocked bool, by [rule names], why text, errors)"""
        full = "\n\n".join(t for _, t in self.policies)
        req = {"principal": f'{PRINCIPAL[0]}::"{PRINCIPAL[1]}"', "action": f'AgentCore::Action::"{PREFIX}{tool}"',
               "resource": f'AgentCore::Gateway::"{self.arn}"', "context": {"input": args}}
        res = cedarpy.is_authorized(req, full, _entities(self.arn, tool))
        errs = list(res.diagnostics.errors)
        by = [self._owner(r) for r in res.diagnostics.reasons]
        if str(res.decision).endswith("NoDecision"):
            return {"decision": "ERROR", "blocked": True, "by": [], "why": "A rule has a typing mistake (see the red message above the rules).", "errors": errs}
        allowed = bool(res.allowed)
        if allowed:
            why = f"Allowed by: {', '.join(by)}."
        elif by:
            why = f"Blocked by the rule: {', '.join(by)} (a forbid rule always wins)."
        else:
            why = "Blocked because NO rule allows it. Everything is denied unless a permit rule says yes."
        skipped = [e for e in errs if "error while evaluating" in e]
        if skipped:
            why += " A rule was skipped because it hit an error: Cedar ignores a rule that cannot be evaluated."
        out = {"decision": "ALLOW" if allowed else "DENY", "by": by, "why": why, "errors": errs}
        out["blocked"] = (not allowed) and self.mode == "ENFORCE"
        if self.mode == "LOG_ONLY" and not allowed:
            out["why"] += " LOG ONLY mode: the call is NOT blocked, only recorded."
        self.log.append({"tool": tool, "args": args, **{k: out[k] for k in ("decision", "blocked", "by")}})
        return out
